#!/usr/bin/env python3
"""Generate the release workflow from machines.json."""

import json


def sdk_name(machine):
    # SDK outputs are named after the architecture; the manual SDK workflow
    # rebuilds the kas machine path as "docker-<arch>".
    if not machine.startswith("docker-"):
        raise SystemExit(f"sdk_machines: {machine} must be a docker-<arch> machine")
    return machine[len("docker-"):]

with open(".github/machines.json") as f:
    data = json.load(f)

branch = data["yocto_branch"]
machines = [m for m in data["machines"] if "tag" in m.get("workflows", [])]
release_outfile = ".github/workflows/release.yaml"

PVTEST_JOBS = [
    "",
    "  pvtest-local:",
    "    needs: build",
    "    uses: ./.github/workflows/call-pvtests.yaml",
    "    with:",
    "      test_path: local",
    "    secrets: inherit",
    "",
    "  pvtest-remote:",
    "    needs: [build, pvtest-local]",
    "    if: always()",
    "    uses: ./.github/workflows/call-pvtests.yaml",
    "    with:",
    "      test_path: remote",
    "    secrets: inherit",
]

SUMMARY_JOB = [
    "",
    "  summary:",
    "    needs: build",
    "    if: always()",
    "    runs-on: ubuntu-latest",
    "    steps:",
    "      - name: Checkout",
    "        uses: actions/checkout@v6",
    "        with:",
    "          ref: ${{ github.ref }}",
    "      - name: Build Summary",
    "        env:",
    "          GH_TOKEN: ${{ github.token }}",
    "        run: |",
    '          echo "## Build Summary" >> $GITHUB_STEP_SUMMARY',
    '          echo "" >> $GITHUB_STEP_SUMMARY',
    '          echo "| Machine | Result |" >> $GITHUB_STEP_SUMMARY',
    '          echo "| :--- | :--- |" >> $GITHUB_STEP_SUMMARY',
    """          gh api repos/${{ github.repository }}/actions/runs/${{ github.run_id }}/jobs | jq -r '.jobs[] | select(.name | contains("build (")) | "| " + (.name | capture("build \\\\((?<m>[^)]+)\\\\)").m) + " | " + (if .conclusion == "success" then "✅" elif .conclusion == "failure" then "❌" elif .conclusion == "cancelled" then "🚫" elif .conclusion == "skipped" then "⏭️" else (.conclusion // "🔄") end) + " |"' >> $GITHUB_STEP_SUMMARY""",
    "      - name: Upload badges to S3",
    "        env:",
    "          GH_TOKEN: ${{ github.token }}",
    "          AWS_ACCESS_KEY_ID: ${{ secrets.AWS_ACCESS_KEY_ID }}",
    "          AWS_SECRET_ACCESS_KEY: ${{ secrets.AWS_SECRET_ACCESS_KEY }}",
    "        run: |",
    "          .github/scripts/upload-badges \\",
    "            ${{ github.repository }} \\",
    "            ${{ github.run_id }} \\",
    "            ${{ github.ref_name }} \\",
    "            ${{ secrets.AWS_S3_BUCKET }}",
]

# Generate release.yaml: build matrix + pvtests + summary, called via workflow_call
release_lines = [
    "# ##############################################################################",
    "# DO NOT EDIT — auto-generated by .github/scripts/make-tag-matrix.py",
    "# Edit that script (and .github/machines.json), then run:",
    "#   .github/scripts/makeworkflows",
    "# Manual changes here will be overwritten on the next run.",
    "# ##############################################################################",
    "",
    f'name: "ontag: make release, build all targets"',
    "",
    "on:",
    "  workflow_call:",
    "",
    "jobs:",
    "  build:",
    '    name: "build (${{ matrix.machine_name }})"',
    "    strategy:",
    "      fail-fast: false",
    "      matrix:",
    "        include:",
]

for m in machines:
    name = m["name"]
    build_target = m.get("build_target", "pantavisor-starter")
    output = m.get("output", "pantavisor-starter*.rootfs.wic*").strip()
    release_lines += [
        f"          - machine_name: {name}-{branch}",
        f"            configs: kas/build-configs/release/{name}-{branch}.yaml:kas/build-configs/shared-vols.yaml",
        f"            build_target: {build_target}",
        f'            output: "{output}"',
    ]

release_lines += [
    "    uses: ./.github/workflows/buildkas-upload.yaml",
    "    with:",
    "      configs: ${{ matrix.configs }}",
    "      machine_name: ${{ matrix.machine_name }}",
    "      build_target: ${{ matrix.build_target }}",
    "      output: ${{ matrix.output }}",
    "    secrets: inherit",
]

sdk_machines = data.get("sdk_machines", [])
if sdk_machines:
    release_lines += [
        "",
        "  build-sdk:",
        '    name: "sdk (${{ matrix.sdk_name }})"',
        "    strategy:",
        "      fail-fast: false",
        "      matrix:",
        "        include:",
    ]
    for name in sdk_machines:
        release_lines += [
            f"          - sdk_name: {sdk_name(name)}",
            f"            configs: kas/machines/{name}.yaml:kas/{branch}.yaml:kas/bsp-base.yaml:kas/sdk.yaml:kas/build-configs/shared-vols.yaml",
        ]
    release_lines += [
        "    uses: ./.github/workflows/buildkas-sdk.yaml",
        "    with:",
        "      configs: ${{ matrix.configs }}",
        "      sdk_name: ${{ matrix.sdk_name }}",
        "      publish: true",
        "    secrets: inherit",
    ]

release_lines += PVTEST_JOBS
release_lines += SUMMARY_JOB

with open(release_outfile, "w") as f:
    f.write("\n".join(release_lines) + "\n")

print(f"new release workflow: {release_outfile}")
